(function (window) {
  function JQ(elements) {
    this.elements = elements || [];
  }
  JQ.prototype.each = function (callback) {
    this.elements.forEach(function (el, index) {
      callback.call(el, index, el);
    });
    return this;
  };
  JQ.prototype.addClass = function (className) {
    return this.each(function () {
      this.classList.add(className);
    });
  };
  JQ.prototype.removeClass = function (className) {
    return this.each(function () {
      this.classList.remove(className);
    });
  };
  JQ.prototype.hasClass = function (className) {
    return this.elements.some(function (el) {
      return el.classList.contains(className);
    });
  };
  JQ.prototype.on = function (event, handler) {
    return this.each(function () {
      this.addEventListener(event, handler);
    });
  };
  JQ.prototype.off = function (event, handler) {
    return this.each(function () {
      this.removeEventListener(event, handler);
    });
  };
  JQ.prototype.find = function (selector) {
    var found = [];
    this.elements.forEach(function (el) {
      found = found.concat(Array.from(el.querySelectorAll(selector)));
    });
    return new JQ(found);
  };

  function $(selector) {
    if (selector instanceof JQ) return selector;
    if (selector instanceof Element || selector === window || selector === document) {
      return new JQ([selector]);
    }
    if (selector instanceof NodeList || Array.isArray(selector)) {
      return new JQ(Array.from(selector));
    }
    return new JQ(Array.from(document.querySelectorAll(selector)));
  }

  $.fn = JQ.prototype;
  window.jQuery = window.$ = $;
})(window);
